function verif1(){
    let cat=document.getElementById("cat").selectedIndex;
    let desc=document.getElementById("desc").value;
    let taille1=document.getElementById("taille1").checked;
    let taille2=document.getElementById("taille2").checked;
    let taille3=document.getElementById("taille3").checked;
    let taille4=document.getElementById("taille4").checked;
    let prix=document.getElementById("prix").value;


    if (cat==0){
        alert("cat incalide");
        return false;
    }
    else if (desc=="" || desc.lenght<10 ||desc.lenght>100 || !verif_alpha(desc.charAt(0)) || !verif_alpha(desc.charAt(desc.length-1)) ){
        alert("description invalide");
        return false;
    }
    else if( !taille1 && !taille2 && !taille3 && !taille4){
        alert("taille invalide");
        return false;
    }
    else if( prix>2000 || prix<100){
        alert("prix invalide");
        return false;
    }
    return true;
}

function verif2(){
    let code=document.getElementById("codehab").value;
    let cin=document.getElementById("cin").value;
    let duree=document.getElementById("duree").value;

    if(!verif_num(code) || code<"1"){
        alert("code habit invalide");
        return false;
    }
    else if(cin.length!=8 || (cin[0]!="1" && cin[0]!="0")){
        alert("cin invalide");
        return false;
    }
    else if(duree.length!=1 || !verif_num(duree) || duree<"1" || duree>"4" ){
        alert("duree invalide");
        return false;
    }
    return true



}



function verif_alpha(ch){
    ch=ch.toUpperCase()
    for(i=0;i<ch.length;i++){
        if ("A">ch[i] || ch[i]>"Z"){
            return false;
        }
    }
    return true;
}

function verif_num(ch){
    for(i=0;i<ch.length;i++){
        if ("0">ch[i] || ch[i]>"9"){
            return false;
        }
    }
    return true;
}

